    assert_eq!(HbarUnit::Millibar.symbol(), "mℏ");
    assert_eq!(HbarUnit::Millibar.base_unit_factor(), 100000);
    assert_eq!(HbarUnit::Hbar.symbol(), "ℏ");
    assert_eq!(HbarUnit::Hbar.base_unit_factor(), 100000000);
    assert_eq!(HbarUnit::Kilobar.symbol(), "kℏ");
    assert_eq!(HbarUnit::Kilobar.base_unit_factor(), 100000000000);
    assert_eq!(HbarUnit::Megabar.symbol(), "Mℏ");
    assert_eq!(HbarUnit::Megabar.base_unit_factor(), 100000000000000);
    assert_eq!(HbarUnit::Gigabar.symbol(), "Gℏ");
    assert_eq!(HbarUnit::Gigabar.base_unit_factor(), 100000000000000000);
